use hs_loop::{dshsearch,uipaint::{UiEvent,Painter},tui::{TuiState,render_skeleton}};
use serde_json::json;
#[test]fn search_projection_reaches_desktop_line_and_fullscreen(){let meta=dshsearch::metadata("grep",&json!({"matches":[{"path":"src/a.rs","lineNumber":2,"line":"needle42"}]}));let event=UiEvent::SearchResult{plugin:"grep".into(),meta:meta.clone()};let wire=event.to_json();assert_eq!(wire["type"],"search_result");assert_eq!(wire["meta"],meta);let mut text=vec![];Painter::new(&mut text,false).handle(&event);let text=String::from_utf8(text).unwrap();assert!(text.contains("src/a.rs")&&text.contains("Line 2: needle42"),"{text}");let mut state=TuiState::default();state.on_ui_event(&event);let mut term=ratatui::Terminal::new(ratatui::backend::TestBackend::new(100,30)).unwrap();term.draw(|f|render_skeleton(f,&state)).unwrap();let buffer=term.backend().buffer();let text=(0..30).map(|y|(0..100).map(|x|buffer[(x,y)].symbol()).collect::<String>()).collect::<Vec<_>>().join("\n");assert!(text.contains("src/a.rs")&&text.contains("Line 2: needle42"),"{text}");}
#[test]fn native_search_session_emits_projection_and_logs_raw_value(){let d=tempfile::tempdir().unwrap();let log=tempfile::tempdir().unwrap();let cfg=d.path().join("rig.toml");std::fs::write(d.path().join("a.rs"),"needle42\n").unwrap();let script=d.path().join("script.jsonl");std::fs::write(&script,"{\"tool\":\"grep\",\"args\":{\"pattern\":\"needle42\",\"include\":\"*.rs\"}}\n").unwrap();std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-scripted"))).unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script);std::env::set_var("HS_PROJECT_ROOT",d.path())}let mut sess=hs_loop::repl::ReplSession::load(&cfg,log.path(),true,Some(1)).unwrap();let seen=std::sync::Arc::new(std::sync::Mutex::new(vec![]));let copy=seen.clone();sess.set_ui_sink(Box::new(move|e|copy.lock().unwrap().push(e.to_json())));let _=sess.run_goal("search fixture");let seen=seen.lock().unwrap();assert!(seen.iter().any(|e|e["type"]=="search_result"&&e["meta"]["files"][0]["path"]=="a.rs"),"{seen:?}");}
